.files-empty-view-body {
	display: flex;
	flex-direction: column;
	height: 100%;
	padding: 4px 8px;
	box-sizing: border-box;
}

/* Welcome/Empty state */
.files-empty-view-body .files-empty-welcome {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	flex: 1;
	padding: 32px;
	text-align: center;
	gap: 8px;
}

.files-empty-view-body .files-empty-welcome-message {
	color: var(--vscode-descriptionForeground);
	font-size: var(--vscode-fontSize-label1);
}

/* Sync Changes Action */
.monaco-workbench .part > .title > .title-actions .action-label.sync-changes-action-view-item {
	display: flex;
	align-items: center;
	gap: 2px;
}
