.chat-terminal-content-part {
	flex: 1 1 auto;
	min-width: 0;
}

/*
 * Intention label layout: when the model supplies an intention, the collapsed
 * terminal-row header shows "<intention> <command>" as two flex cells on a
 * single non-wrapping line. Each cell ellipsis-truncates and they split the
 * available width equally when the content overflows the row.
 */
.chat-terminal-thinking-collapsible.chat-terminal-has-intention .chat-used-context-label {
	width: 100%;
	max-width: 100%;
}

.chat-terminal-thinking-collapsible.chat-terminal-has-intention .monaco-button.monaco-icon-button {
	width: fit-content;
	max-width: 100%;
	justify-content: flex-start;
}

.chat-terminal-thinking-collapsible.chat-terminal-has-intention .monaco-button-mdlabel {
	flex: 1 1 auto;
	min-width: 0;
}

.chat-terminal-label-flex {
	display: flex;
	flex-direction: row;
	flex-wrap: nowrap;
	align-items: baseline;
	column-gap: 4px;
	min-width: 0;
	width: 100%;
}

.chat-terminal-label-flex > .chat-terminal-intention,
.chat-terminal-label-flex > .chat-terminal-command {
	/* Natural width so short content stays inline and adjacent; only shrink
	 * (dividing the available space) once the row would overflow. */
	flex: 0 1 auto;
	min-width: 0;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.chat-terminal-label-flex > .chat-terminal-command > code {
	white-space: nowrap;
}

.chat-terminal-label-flex > .chat-terminal-label-suffix {
	flex: 0 0 auto;
	white-space: nowrap;
}

.chat-terminal-progress-row > div:first-child {
	display: none;
}

.chat-terminal-content-part .chat-terminal-content-title {
	border: 1px solid var(--vscode-chat-requestBorder);
	border-radius: var(--vscode-cornerRadius-medium);
	padding: 0px 9px 0px 5px;
	max-width: 100%;
	box-sizing: border-box;
	display: flex;
	flex-direction: row;
	align-items: flex-start;
	gap: 12px;

	.rendered-markdown {
		display: flex;
		column-gap: 4px;

		p {
			margin: 0 !important;
		}

		.monaco-tokenized-source {
			background: transparent !important;
		}
	}
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block {
	display: flex;
	gap: 0px;
	align-items: flex-start;
	flex: 1 1 auto;
	min-width: 0;
	padding-top: 1px;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block > .rendered-markdown {
	flex: 1 1 auto;
	min-width: 0;
	display: flex;
	column-gap: 4px;
	align-items: center;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block > .rendered-markdown p {
	display: inline-flex;
	align-items: center;
	column-gap: 4px;
	margin: 0 !important;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block > .rendered-markdown .monaco-tokenized-source {
	background: transparent !important;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block > .rendered-markdown code {
	font-size: var(--vscode-chat-font-size-body-xs);
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .chat-terminal-command-decoration,
.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .terminal-command-decoration {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	font-size: 13px;
	width: 16px;
	height: 16px;
	flex-shrink: 0;
	margin-top: 2px;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .chat-terminal-command-decoration.success,
.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .terminal-command-decoration.success {
	color: var(--vscode-terminalCommandDecoration-successBackground) !important;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .chat-terminal-command-decoration.default-color,
.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .terminal-command-decoration.default-color {
	color: var(--vscode-terminalCommandDecoration-defaultBackground) !important;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .chat-terminal-command-decoration.error,
.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .terminal-command-decoration.error {
	color: var(--vscode-terminalCommandDecoration-errorBackground) !important;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .chat-terminal-command-decoration.default,
.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .terminal-command-decoration.default {
	pointer-events: none;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .chat-terminal-command-decoration .monaco-pixel-spinner {
	display: none;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .chat-terminal-command-decoration.chat-terminal-running-spinner {
	color: var(--vscode-terminalCommandDecoration-defaultBackground);
	pointer-events: none;
	margin-right: 3px;
	margin-left: 2px;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .chat-terminal-command-decoration.chat-terminal-running-spinner .monaco-pixel-spinner {
	display: inline-grid;
}

.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .chat-terminal-command-decoration:focus-visible,
.chat-terminal-content-part .chat-terminal-content-title .chat-terminal-command-block .terminal-command-decoration:focus-visible {
	outline: 1px solid var(--vscode-focusBorder);
	outline-offset: 2px;
}

.chat-terminal-content-part .chat-terminal-action-bar {
	display: flex;
	gap: 4px;
	margin-left: auto;
	align-self: center;
}

/* Reset margin for action bar icons - they should have similar spacing to other action bars */
.chat-terminal-content-part .chat-terminal-action-bar .monaco-action-bar .codicon {
	margin: 0;
}

.chat-terminal-content-part .chat-terminal-content-message {
	.rendered-markdown {
		white-space: normal;
		line-height: normal;

		& > p {
			color: var(--vscode-descriptionForeground);
			font-size: var(--vscode-chat-font-size-body-s);
			margin: 0 !important;

			code {
				font-size: var(--vscode-chat-font-size-body-xs);
			}
		}
	}
}

.chat-terminal-output-container {
	border: 1px solid var(--vscode-chat-requestBorder);
	border-bottom-left-radius: var(--vscode-cornerRadius-medium);
	border-bottom-right-radius: var(--vscode-cornerRadius-medium);
	max-height: 300px;
	box-sizing: border-box;
	overflow: hidden;
	position: relative;
	max-width: 100%;
	padding: 0;
}

/* Keep collapsed output fully hidden so it cannot contribute an extra border line. */
.chat-terminal-output-container.collapsed,
.chat-terminal-output-container:not(.expanded) {
	display: none;
}

.chat-terminal-content-part .chat-terminal-content-title.chat-terminal-content-title-no-bottom-radius {
	border-bottom-left-radius: 0px;
	border-bottom-right-radius: 0px;
	border-bottom: 0;
}

.chat-terminal-output-container.expanded {
	display: block;
}
.chat-terminal-output-container > .monaco-scrollable-element {
	width: 100%;
	background: inherit;
}
.chat-terminal-output-container.chat-terminal-output-container-no-output .chat-terminal-output-body {
	padding-bottom: 5px;
}
.chat-terminal-output-container:focus-visible {
	outline: 1px solid var(--vscode-focusBorder);
	outline-offset: 2px;
}
div.chat-terminal-content-part.progress-step > div.chat-terminal-output-container.expanded > div > div.chat-terminal-output-body > div > div.chat-terminal-output-terminal > div > div.xterm-scrollable-element {
	margin-left: -12px;
	margin-right: -12px;
	padding-left: 12px;
	padding-right: 12px;
	box-sizing: border-box;
	background: inherit;
}
.chat-terminal-output-body {
	padding: 5px 0px 3px;
	max-width: 100%;
	box-sizing: border-box;
	min-height: 0;
	background: inherit;
}
.chat-terminal-output-content {
	background: inherit;
}
.chat-terminal-output-terminal {
	background: inherit;
}
.chat-terminal-output-terminal .xterm-viewport {
	background: inherit !important;
}

.chat-terminal-output-terminal.chat-terminal-output-terminal-no-output {
	display: none;
}
.chat-terminal-output-empty {
	display: none;
	font-style: italic;
	color: var(--vscode-descriptionForeground);
	line-height: normal;
	padding-left: 12px;
}
.chat-terminal-output-terminal.chat-terminal-output-terminal-no-output ~ .chat-terminal-output-empty {
	display: block;
}

.chat-terminal-output-container .xterm-scrollable-element .xterm-scrollbar {
	display: none;
}

/* Allow clicks to pass through scrollbar track to reach inline links, but keep slider draggable */
.chat-terminal-output-container > .monaco-scrollable-element > .scrollbar.horizontal {
	pointer-events: none;
}

.chat-terminal-output-container > .monaco-scrollable-element > .scrollbar.horizontal .slider {
	pointer-events: auto;
}

.chat-used-context-label .chat-terminal-show-link {
	color: var(--vscode-textLink-foreground);
	cursor: pointer;
	text-decoration: none;
}

.chat-used-context-label .chat-terminal-show-link:hover {
	text-decoration: underline;
	color: var(--vscode-textLink-activeForeground);
}

.chat-terminal-show-link-container {
	display: inline;
	white-space: nowrap;
}
