.interactive-session .interactive-response .value .chat-thinking-box {
	outline: none;
	position: relative;
	color: var(--vscode-descriptionForeground);

	contain: layout style;

	.chat-thinking-external-resources {
		margin-top: 4px;
		margin-left: 5px;
	}

	.chat-used-context {
		margin: 0px;
	}

	> .chat-used-context-label {
		position: relative;
	}

	> .chat-used-context-label .monaco-button.monaco-icon-button {
		display: inline-flex;
		align-items: center;
		line-height: 1.5em;
		font-size: 13px;

		&.chat-thinking-title-with-diff {
			padding-right: var(--vscode-spacing-size20);
		}

		.monaco-button-mdlabel {
			font-size: var(--vscode-chat-font-size-body-s);
		}

		.codicon {
			font-size: var(--vscode-codiconFontSize-compact);
		}

		.chat-thinking-title-detail-text {
			opacity: 0.7;
		}
	}

	> .chat-used-context-label .rendered-markdown.collapsible-title-content {
		line-height: unset;
	}

	> .chat-used-context-label .rendered-markdown.chat-thinking-title-detail {
		display: inline;
		font-size: inherit;
		line-height: inherit;

		> p {
			display: inline;
			margin: 0;
		}
	}

	> .chat-used-context-label > .rendered-markdown.chat-thinking-title-detail {
		cursor: pointer;
	}

	> .chat-used-context-label > .chat-thinking-title-diff.monaco-button {
		display: inline-flex;
		align-items: center;
		padding: var(--vscode-spacing-size20) var(--vscode-spacing-size40);
		margin-left: var(--vscode-spacing-sizeNone);
		border-radius: var(--vscode-cornerRadius-small);
		gap: var(--vscode-spacing-size40);
		background: transparent;
		color: inherit;
		line-height: 1.5em;
		cursor: pointer;

		> .label-added {
			color: var(--vscode-chat-linesAddedForeground);
		}

		> .label-removed {
			color: var(--vscode-chat-linesRemovedForeground);
		}

		&:hover,
		&.hovered {
			background-color: var(--vscode-toolbar-hoverBackground);
			color: var(--vscode-foreground);
		}

		&:focus {
			outline: none;
		}

		&:focus-visible {
			outline: var(--vscode-strokeThickness) solid var(--vscode-focusBorder);
			outline-offset: calc(-1 * var(--vscode-strokeThickness));
		}
	}

	> .chat-used-context-label > .chat-collapsible-hover-chevron {
		vertical-align: middle;
	}

	> .chat-used-context-label:hover > .chat-collapsible-hover-chevron {
		opacity: 1;
	}

	&.chat-thinking-active > .chat-used-context-label .monaco-button.monaco-icon-button {

		.codicon.codicon-circle-filled-compact {
			display: none;
		}
	}

	&.chat-thinking-active.chat-used-context-collapsed > .chat-used-context-label .monaco-button.monaco-icon-button {

		.chat-thinking-title-shimmer {
			background: linear-gradient(90deg,
					var(--vscode-descriptionForeground) 0%,
					var(--vscode-descriptionForeground) 30%,
					var(--vscode-chat-thinkingShimmer) 50%,
					var(--vscode-descriptionForeground) 70%,
					var(--vscode-descriptionForeground) 100%);
			background-size: 400% 100%;
			background-clip: text;
			-webkit-background-clip: text;
			-webkit-text-fill-color: transparent;
			animation: chat-thinking-shimmer 2s linear infinite;
			will-change: background-position;
		}
	}

	/* shimmer animation stuffs */
	.chat-thinking-spinner-item .chat-thinking-spinner-label {
		background: linear-gradient(90deg,
				var(--vscode-descriptionForeground) 0%,
				var(--vscode-descriptionForeground) 30%,
				var(--vscode-chat-thinkingShimmer) 50%,
				var(--vscode-descriptionForeground) 70%,
				var(--vscode-descriptionForeground) 100%);
		background-size: 400% 100%;
		background-clip: text;
		-webkit-background-clip: text;
		-webkit-text-fill-color: transparent;
		animation: chat-thinking-shimmer 2s linear infinite;
		will-change: background-position;
	}

	&:not(.chat-used-context-collapsed) .chat-used-context-list.chat-thinking-collapsible {
		overflow: visible;
		max-height: none;
	}

	/* Curved connector from the header to the first thinking item */
	&:not(.chat-used-context-collapsed) > .chat-used-context-label::after {
		content: '';
		position: absolute;
		left: 3px;
		top: 100%;
		height: 16px;
		width: 5px;
		border-left: 1px solid var(--vscode-chat-requestBorder);
		border-bottom: 1px solid var(--vscode-chat-requestBorder);
		border-bottom-left-radius: 5px;
	}

	.monaco-button.hidden,
	.chat-pinned-preview.hidden {
		display: none;
	}

	.chat-used-context-list.chat-thinking-collapsible {
		border: none;
		border-radius: 0;
		margin-bottom: 0;
		position: relative;
		overflow: hidden;
		padding-top: 0;
		margin-left: 5px;

		.chat-tool-invocation-part {
			padding: 4px 12px 4px 18px;
			position: relative;
		}

		.chat-thinking-tool-wrapper {
			.chat-used-context {
				margin-bottom: 0px;
				margin-left: 4px;
				padding-left: 2px;

				.monaco-button.monaco-text-button {
					color: var(--vscode-descriptionForeground);
					display: flex;
					align-items: center;

					:hover {
						color: var(--vscode-foreground);
					}

					.monaco-button:hover .chat-collapsible-hover-chevron {
						opacity: 1;
					}
				}
			}

			.chat-used-context:not(.chat-used-context-collapsed) {
				.monaco-button.monaco-text-button {
					color: var(--vscode-foreground);
				}
			}

			.progress-container,
			.chat-confirmation-widget-container {
				margin: 0 0 0 6px;
				box-sizing: border-box;
				max-width: calc(100% - 6px);
			}

			/* todo: ideally not !important, but the competing css has 14 specificity */
			.codicon.codicon-check-compact,
			.codicon.codicon-loading-compact {
				display: none !important;
			}

			.chat-collapsible-hover-chevron.codicon {
				display: inline-flex;
			}

			.show-checkmarks .chat-confirmation-widget-title > .codicon:first-child:not(.chat-collapsible-hover-chevron) {
				display: inline-block;
			}

			.show-checkmarks .progress-container > .codicon.codicon-check-compact {
				display: inline-flex;
			}

			.chat-used-context.chat-hook-outcome-blocked,
			.chat-used-context.chat-hook-outcome-warning {
				padding: 4px 12px 4px 20px;
				margin-bottom: 0;
			}
		}

		.chat-thinking-item.markdown-content {
			padding: 6px 12px 6px 24px;
			position: relative;
			font-size: var(--vscode-chat-font-size-body-s);

			.progress-container {
				margin-bottom: 0px;
				padding-top: 0px;
			}

			[data-code] {
				background-color: var(--vscode-textPreformat-background);
				padding: 1px 3px;
				border-radius: 4px;
				border: 1px solid var(--vscode-textPreformat-border);
				white-space: pre-wrap;
			}
		}

		.chat-thinking-tool-wrapper .chat-markdown-part.rendered-markdown {
			padding: 5px 12px 4px 24px;

			.status-icon.codicon-check-compact {
				display: none;
			}

			.show-checkmarks .status-icon.codicon-check-compact {
				display: inline-flex;
			}

			.code:has(.chat-codeblock-pill-container) {
				margin-bottom: 0px;

				.chat-codeblock-pill-container {
					margin-bottom: 0px;
				}
			}
		}

		/*
		 * External-edit pills (agent host) sit directly inside
		 * `.chat-thinking-tool-wrapper` rather than nested inside a markdown
		 * code block, so they need the same left padding to clear the
		 * absolutely-positioned thinking icon.
		 */
		.chat-thinking-tool-wrapper > .chat-codeblock-pill-container {
			padding: 5px 12px 4px 24px;

			.status-icon.codicon-check-compact {
				display: none;
			}

			.show-checkmarks .status-icon.codicon-check-compact {
				display: inline-flex;
			}
		}

		.chat-confirmation-widget2 .chat-confirmation-message-terminal-disclaimer .chat-markdown-part.rendered-markdown {
			padding: 2px 0px;
		}

		.chat-thinking-tool-wrapper .chat-terminal-thinking-content .chat-markdown-part.rendered-markdown {
			padding: 0;
		}

		/* chain of thought lines */
		.chat-thinking-tool-wrapper,
		.chat-thinking-item.markdown-content,
		.chat-thinking-spinner-item {
			position: relative;

			&::before {
				content: '';
				position: absolute;
				left: 10.5px;
				top: 0px;
				bottom: 0px;
				width: 1px;
				border-radius: 0;
				background-color: var(--vscode-chat-requestBorder);
				mask-image: linear-gradient(to bottom, #000 0 5px, transparent 5px 25px, #000 24px 100%);
			}

			&:first-child::before {
				mask-image: linear-gradient(to bottom, transparent 0 25px, #000 25px 100%);
			}

			&:last-child::before {
				mask-image: linear-gradient(to bottom, #000 0 5px, transparent 5px 100%);
			}

			&:only-child::before {
				background: none;
				mask-image: none;
			}

			> .chat-thinking-icon {
				position: absolute;
				left: 5px;
				top: 9px;
				width: 12px;
				height: 12px;
				font-size: var(--vscode-codiconFontSize-compact);
				line-height: 12px;
				text-align: center;
				color: var(--vscode-descriptionForeground);
			}

			/* the default book icon has a pixel of space at the bottom */
			> .chat-thinking-icon .codicon.codicon-book {
				top: 10px;
			}
		}

		.chat-thinking-spinner-item {
			padding: 6px 12px 6px 24px;
			font-size: var(--vscode-chat-font-size-body-s);

			.chat-thinking-spinner-label {
				color: var(--vscode-descriptionForeground);
			}
		}
	}

	.chat-thinking-item {
		padding: 6px 12px;
		position: relative;

		.progress-container {
			margin-bottom: 0px;
			padding-top: 0px;
		}
	}

	.chat-thinking-text {
		font-size: var(--vscode-chat-font-size-body-s);
		padding: 0 10px;
		display: block;
	}

	.rendered-markdown > p {
		margin: 0;

		& + p {
			margin-top: 5px;
		}
	}
}

.interactive-session .interactive-response .value .chat-used-context.chat-terminal-thinking-collapsible {
	display: flex;
	flex-direction: column;
	width: 100%;

	.monaco-button.monaco-text-button {
		display: flex;
		align-items: center;
	}

	.chat-used-context-list.chat-terminal-thinking-content {
		border: none;
		padding: 0;
		margin-bottom: 2px;
		overflow: hidden;

		.codicon:not(.codicon-check-compact, .codicon-loading-compact) {
			display: inline-flex;
		}

		.progress-container {
			margin: 0;
		}
	}

	.chat-terminal-thinking-content .rendered-markdown [data-code] {
		margin-bottom: 0px;
	}
}

.interactive-session .interactive-response .value .chat-thinking-fixed-mode {
	outline: none;

	/* Hide the header/collapse button while streaming — it reappears when chat-thinking-streaming is removed */
	&:has(.chat-thinking-streaming) > .chat-used-context-label {
		display: none;
	}

	> .monaco-scrollable-element > .shadow {
		display: none;
	}

	/* Directional fade indicators via mask-image on the scrollable viewport */
	&.chat-thinking-fade-top > .monaco-scrollable-element {
		mask-image: linear-gradient(to bottom, transparent 0px, black 20px);
		-webkit-mask-image: linear-gradient(to bottom, transparent 0px, black 20px);
	}

	&.chat-thinking-fade-bottom > .monaco-scrollable-element {
		mask-image: linear-gradient(to top, transparent 0px, black 20px);
		-webkit-mask-image: linear-gradient(to top, transparent 0px, black 20px);
	}

	&.chat-thinking-fade-top.chat-thinking-fade-bottom > .monaco-scrollable-element {
		mask-image: linear-gradient(to bottom, transparent 0px, black 20px, black calc(100% - 20px), transparent 100%);
		-webkit-mask-image: linear-gradient(to bottom, transparent 0px, black 20px, black calc(100% - 20px), transparent 100%);
	}

	> .monaco-scrollable-element:has(.chat-used-context-list.chat-thinking-collapsible:not(.chat-thinking-streaming)) {
		overflow: hidden;
		height: auto;
		opacity: 1;

		> .scrollbar {
			display: none;
		}
	}

	&.chat-thinking-fixed-mode-animated > .monaco-scrollable-element {
		transition:
			max-height 180ms cubic-bezier(0.2, 0, 0, 1),
			opacity 140ms cubic-bezier(0.2, 0, 0, 1);
	}

	&.chat-used-context-collapsed > .monaco-scrollable-element:has(.chat-used-context-list.chat-thinking-collapsible:not(.chat-thinking-streaming)) {
		display: block;
		opacity: 0;

		> .chat-used-context-list.chat-thinking-collapsible {
			display: block;
		}
	}

	&.chat-used-context-collapsed .chat-used-context-list.chat-thinking-collapsible.chat-thinking-streaming {
		max-height: 200px;
		overflow: hidden;
		display: block;
		margin-left: 0px;
		padding-left: 0px;

		.chat-tool-invocation-part {
			padding-left: 13px;
		}

		.chat-thinking-spinner-item {
			padding-left: 19px;
		}

		.chat-used-context.chat-hook-outcome-blocked,
		.chat-used-context.chat-hook-outcome-warning {
			padding-left: 15px;
		}

		.chat-thinking-item.markdown-content {
			padding-left: 19px;
		}

		.chat-thinking-tool-wrapper .chat-markdown-part.rendered-markdown {
			padding-left: 19px;
		}

		.chat-thinking-tool-wrapper > .chat-codeblock-pill-container {
			padding-left: 19px;
		}

		/* chain of thought lines */
		.chat-thinking-tool-wrapper,
		.chat-thinking-item.markdown-content,
		.chat-thinking-spinner-item {
			&::before {
				left: 5.5px;
			}

			> .chat-thinking-icon {
				left: 0px;
			}
		}
	}

	&:not(.chat-used-context-collapsed) .chat-used-context-list.chat-thinking-collapsible.chat-thinking-streaming {
		max-height: none;
		overflow: visible;
		display: block;
	}

	&:not(.chat-used-context-collapsed) > .monaco-scrollable-element:has(.chat-thinking-streaming) {
		overflow: visible;
		height: auto;
	}

	.chat-used-context-list.chat-thinking-collapsible:not(.chat-thinking-streaming) {
		max-height: none;
		overflow: visible;
	}

	.chat-thinking-tool-wrapper .chat-used-context:not(.chat-used-context-collapsed) .chat-used-context-list {
		display: block;
	}
}

.editor-instance .interactive-session .interactive-response .value .chat-thinking-box .chat-thinking-item ::before {
	background: var(--vscode-editor-background);
}

.monaco-reduce-motion .chat-thinking-fixed-mode > .monaco-scrollable-element,
.monaco-workbench.monaco-reduce-motion .chat-thinking-fixed-mode > .monaco-scrollable-element {
	transition: none !important;
}

@media (prefers-reduced-motion: reduce) {
	.chat-thinking-fixed-mode > .monaco-scrollable-element {
		transition: none !important;
	}
}

.interactive-session .interactive-response .value .chat-thinking-box .chat-used-context-label code {
	display: inline;
	line-height: inherit;
	padding: 1px 3px;
}
